static int r8153b_mcu_spdown_en(struct r8152 *tp, bool enable)
{
	int ret;

	if (enable)
		ret = ocp_word_set_bits(tp, MCU_TYPE_PLA, PLA_MAC_PWR_CTRL3,
					PLA_MCU_SPDWN_EN);
	else
		ret = ocp_word_clr_bits(tp, MCU_TYPE_PLA, PLA_MAC_PWR_CTRL3,
					PLA_MCU_SPDWN_EN);

	return ret;
}
